package com.akira.one;
import android.os.Bundle;import android.text.*;import android.widget.*;import androidx.appcompat.app.AlertDialog;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import org.json.*;import java.util.*;
public class SearchActivity extends BaseActivity{
 private final List<ContentItem> all=new ArrayList<>(),shown=new ArrayList<>();private ContentAdapter adapter;private EditText search;private int pending=3;
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_search);RecyclerView rv=findViewById(R.id.searchRecycler);rv.setLayoutManager(new GridLayoutManager(this,3));adapter=new ContentAdapter(shown,new ContentAdapter.Listener(){public void onClick(ContentItem i){ContentNavigator.open(SearchActivity.this,i);}public void onLongClick(ContentItem i){context(i);}});rv.setAdapter(adapter);search=findViewById(R.id.globalSearch);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){filter();}public void afterTextChanged(Editable e){}});load("live");load("movie");load("series");}
 private void load(String type){XtreamClient.ArrayCallback cb=new XtreamClient.ArrayCallback(){public void onSuccess(JSONArray a){for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;String id="series".equals(type)?o.optString("series_id"):o.optString("stream_id");String icon="series".equals(type)?o.optString("cover"):o.optString("stream_icon");String source="live".equals(type)?o.optString("direct_source",""):"";all.add(new ContentItem(id,o.optString("name"),icon,type,o.optString("container_extension","mp4"),"live".equals(type)?"TV ao Vivo":"movie".equals(type)?"Filme":"Série",o.optString("category_id"),source));}done();}public void onError(Exception e){done();}};if("live".equals(type))XtreamClient.getLive(this,cb);else if("movie".equals(type))XtreamClient.getMovies(this,cb);else XtreamClient.getSeries(this,cb);}
 private void done(){pending--;filter();((TextView)findViewById(R.id.searchStatus)).setText(pending>0?"Carregando catálogos...":all.size()+" itens indexados");}
 private void filter(){String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);shown.clear();if(!q.isBlank())for(ContentItem i:all)if(i.name.toLowerCase(Locale.ROOT).contains(q))shown.add(i);adapter.notifyDataSetChanged();}
 private void context(ContentItem i){String[] a="live".equals(i.type)?new String[]{Prefs.isFavorite(this,i)?"Remover dos favoritos":"Adicionar aos favoritos","Ver EPG"}:new String[]{Prefs.isFavorite(this,i)?"Remover dos favoritos":"Adicionar aos favoritos"};new AlertDialog.Builder(this).setTitle(i.name).setItems(a,(d,w)->{if(w==0){Prefs.toggleFavorite(this,i);Toast.makeText(this,"Favoritos atualizados",Toast.LENGTH_SHORT).show();}else{android.content.Intent in=new android.content.Intent(this,EpgActivity.class);in.putExtra("stream_id",i.id);in.putExtra("title",i.name);startActivity(in);}}).show();}
}
